# Add only the JSON accessors used by the real service; string copies remain an honest fake seam.
sources['org/json/JSONObject.java']=sources['org/json/JSONObject.java'].replace('public String toString()', 'public boolean getBoolean(String k){return (Boolean)values.get(k);}public JSONArray getJSONArray(String k){return (JSONArray)values.get(k);}public String toString()')
